declare_lint_rule! {
    /// Enforce passing a type parameter to `Array#reduce` instead of using a type assertion
    /// on the initial value.
    ///
    /// When the initial value of `Array#reduce` or `Array#reduceRight` uses a type assertion
    /// (`as Type` or `<Type>expr`), TypeScript no longer checks that the reducer callback
    /// actually returns that type. Passing the type as a type parameter on the call lets
    /// TypeScript verify the return type of the callback instead.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduce((acc, n) => [...acc, n], [] as number[]);
    /// ```
    ///
    /// ```ts,expect_diagnostic
    /// [1, 2, 3].reduceRight((acc, n) => [...acc, n], <number[]>[]);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```ts
    /// [1, 2, 3].reduce<number[]>((acc, n) => [...acc, n], []);
    /// ```
    ///
    /// ```ts
    /// [1, 2, 3].reduce((acc, n) => acc + n, 0);
    /// ```
    pub UseReduceTypeParameter {
        version: "next",
        name: "useReduceTypeParameter",
        language: "ts",
        recommended: false,
        severity: Severity::Information,
        fix_kind: FixKind::Unsafe,
    }
}

pub struct RuleState {
    /// Whether the method is `reduceRight` (`false` means `reduce`).
    is_reduce_right: bool,
    /// The initial value expression that carries the type assertion.
    initial_value: AnyJsExpression,
    /// The expression with the type assertion removed.
    inner_expression: AnyJsExpression,
    /// The type used in the assertion, to be moved to a type parameter.
    asserted_type: AnyTsType,
    /// Whether the call already has a type parameter.
    has_type_arguments: bool,
}

impl Rule for UseReduceTypeParameter {
    type Query = Ast<JsCallExpression>;
    type State = RuleState;
    type Signals = Option<Self::State>;
    type Options = UseReduceTypeParameterOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();

        let callee = call.callee().ok()?;
        let member = AnyJsMemberExpression::cast(callee.into_syntax())?;
        let member_name = member.member_name()?;
        let is_reduce_right = match member_name.text() {
            "reduce" => false,
            "reduceRight" => true,
            _ => return None,
        };

        // The initial value is the second argument.
        let arguments = call.arguments().ok()?;
        let initial_value = arguments.args().iter().nth(1)?.ok()?;
        let initial_value = initial_value.as_any_js_expression()?.clone();

        let (asserted_type, inner_expression) = extract_type_assertion(&initial_value)?;

        Some(RuleState {
            is_reduce_right,
            initial_value,
            inner_expression,
            asserted_type,
            has_type_arguments: call.type_arguments().is_some(),
        })
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let method = if state.is_reduce_right {
            "reduceRight"
        } else {
            "reduce"
        };
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.initial_value.range(),
                markup! {
                    "The initial value of Array#"{method}" uses a type assertion."
                },
            )
            .note(markup! {
                "Type assertions can hide type mismatches in the reducer callback. Use a type parameter on the call instead, so TypeScript checks the return type."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, state: &Self::State) -> Option<JsRuleAction> {
        let call = ctx.query();
        let mut mutation = ctx.root().begin();

        // Remove the type assertion from the initial value.
        let call_without_assertion = call
            .clone()
            .replace_node(state.initial_value.clone(), state.inner_expression.clone())?;

        let (new_call, message) = if state.has_type_arguments {
            (
                call_without_assertion,
                markup! { "Remove the type assertion from the initial value." }.to_owned(),
            )
        } else {
            // Move the asserted type to a type parameter on the call.
            let type_arguments = make::ts_type_arguments(
                make::token(T![<]),
                make::ts_type_argument_list([state.asserted_type.clone().trim_trivia()?], []),
                make::token(T![>]),
            );
            let new_call = make::js_call_expression(
                call_without_assertion.callee().ok()?,
                call_without_assertion.arguments().ok()?,
            )
            .with_type_arguments(type_arguments)
            .build();
            (
                new_call,
                markup! { "Use a type parameter instead of type assertion." }.to_owned(),
            )
        };

        mutation.replace_node(call.clone(), new_call);

        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            message,
            mutation,
        ))
    }
}

/// Unwraps a type assertion from an expression, returning the asserted type and the
/// inner expression with the assertion removed.
///
/// Handles `expr as Type`, `<Type>expr`, and parenthesized forms of both.
fn extract_type_assertion(expression: &AnyJsExpression) -> Option<(AnyTsType, AnyJsExpression)> {
    match expression {
        AnyJsExpression::TsAsExpression(as_expression) => {
            Some((as_expression.ty().ok()?, as_expression.expression().ok()?))
        }
        AnyJsExpression::TsTypeAssertionExpression(assertion) => {
            Some((assertion.ty().ok()?, assertion.expression().ok()?))
        }
        AnyJsExpression::JsParenthesizedExpression(parenthesized) => {
            extract_type_assertion(&parenthesized.expression().ok()?)
        }
        _ => None,
    }
}
